WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xc_analogy_extension'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '外延关系概述', 'kp-xc-analogy-extension-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"外延关系概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"识别特征：","marks":[{"type":"bold"}]},{"type":"text","text":"词语之间在概念范围上的关系 — 谁包含谁、谁和谁并列、谁和谁交叉。约占类比推理的 42%。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"全同关系：两个词指同一事物（如「番茄:西红柿」）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"并列关系：同属一个大类（如「苹果:香蕉」）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"交叉关系：部分重叠（如「大学生:运动员」）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"包容关系：种属（苹果:水果）或整体部分（轮胎:汽车）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"全异关系：完全不重叠（如「猫:桌子」）"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、判断方法"}]},{"type":"paragraph","content":[{"type":"text","text":"用「是」字造句判断："}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A 是 B 且 B 是 A → 全同关系"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A 是 B 的一种 → 种属（包容）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A 是 B 的一部分 → 整体部分（包容）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"有的 A 是 B，有的 A 不是 B → 交叉"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A 不是 B 且 B 不是 A → 全异"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"学习建议：","marks":[{"type":"bold"}]},{"type":"text","text":"外延关系是类比推理的基础，包容关系（740 题）和并列关系（472 题）是最高频的两个考点。"}]}]}]}$$ AS jsonb), NULL, '外延关系概述：全同、并列、交叉、包容、全异的识别与判断方法。', category_node.id, CAST('["类比推理", "外延关系", "概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xc_analogy_extension", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
